-- BF-049: seeded compliance policies (needs_legal_review) and offer relevance. Generated by src/cli/compliance-seeds.ts.
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e3-718c-b744-92e5ed9ebe28', NULL, '*', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"No policy is seeded for this jurisdiction, so the applicable rules are unknown; the message can only be sent manually after a person checks the local requirements.","fr":"Aucune politique n''est définie pour ce territoire, les règles applicables sont donc inconnues ; le message ne peut être envoyé que manuellement après vérification des exigences locales par une personne."},"rules":[],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e3-718c-b744-958681ad4b7d', NULL, '*', 'letter', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"No policy is seeded for this jurisdiction; a person must check the local rules on postal marketing before sending.","fr":"Aucune politique n''est définie pour ce territoire ; une personne doit vérifier les règles locales sur la prospection postale avant l''envoi."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e3-718c-b744-9be7c66fb973', NULL, '*', 'phone', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"No policy is seeded for this jurisdiction; a person must check the local telemarketing rules before calling.","fr":"Aucune politique n''est définie pour ce territoire ; une personne doit vérifier les règles locales de démarchage téléphonique avant d''appeler."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e3-718c-b744-9f9845dfca02', NULL, '*', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"No policy is seeded for this jurisdiction; a person must check the local rules on SMS marketing before sending.","fr":"Aucune politique n''est définie pour ce territoire ; une personne doit vérifier les règles locales sur le marketing par SMS avant l''envoi."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e3-718c-b744-a2197161445b', NULL, '*', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-de0e76be219a', NULL, 'BE', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Belgium requires prior consent except for impersonal addresses of legal persons; when the address or recipient type is unknown the message must be handled by a person.","fr":"La Belgique exige un consentement préalable sauf pour les adresses impersonnelles de personnes morales ; lorsque le type d''adresse ou de destinataire est inconnu, le message doit être traité par une personne."},"rules":[{"id":"offer-not-relevant","when":{"relevance":["not_relevant"]},"decision":"blocked","explain":{"en":"The offer does not relate to the recipient''s business activity, so the message cannot be justified as professional prospecting.","fr":"L''offre ne concerne pas l''activité professionnelle du destinataire : le message ne peut pas être justifié comme une prospection professionnelle."}},{"id":"personal-address","when":{"addressType":["personal"]},"decision":"blocked","explain":{"en":"A personal address at a company domain identifies a natural person and requires prior consent in Belgium.","fr":"Une adresse nominative sur un domaine d''entreprise identifie une personne physique et requiert un consentement préalable en Belgique."}},{"id":"sole-trader","when":{"recipientType":["sole_trader"]},"decision":"blocked","explain":{"en":"The exception for impersonal addresses only applies to offers aimed at legal persons; a sole trader is a natural person and must consent first.","fr":"L''exception pour les adresses impersonnelles ne vaut que pour les offres destinées aux personnes morales ; un indépendant est une personne physique et doit consentir au préalable."}},{"id":"impersonal-legal-person","when":{"recipientType":["legal_person"],"addressType":["generic","department"]},"decision":"allowed_with_conditions","explain":{"en":"An impersonal address (info@, sales@) of a legal person may receive offers aimed at the legal person without prior consent, with sender identification and an opt-out.","fr":"Une adresse impersonnelle (info@, sales@) d''une personne morale peut recevoir des offres destinées à cette personne morale sans consentement préalable, avec identification de l''expéditeur et désabonnement."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-e06cd0c2f9fd', NULL, 'BE', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-e7e2dbd87cfe', NULL, 'BE', 'phone', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Belgium has separate rules for telephone prospecting (including the Do Not Call Me list); calls must be prepared and placed by a person who checks them first.","fr":"La Belgique applique des règles distinctes au démarchage téléphonique (dont la liste « Ne m''appelez plus ») ; les appels doivent être préparés et passés par une personne qui les vérifie au préalable."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-e83f2d8b285d', NULL, 'BE', 'sms', 1, 'seed', '{"default":"blocked","defaultExplain":{"en":"Unsolicited SMS to a mobile number reaches a natural person and requires prior consent in Belgium; the channel is blocked for prospecting.","fr":"Un SMS non sollicité vers un numéro mobile atteint une personne physique et requiert un consentement préalable en Belgique ; le canal est bloqué pour la prospection."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-ee9b15187799', NULL, 'BE', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-f3cac7ce3c4d', NULL, 'BL', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"The address type or the relevance of the offer could not be established, so the message must be reviewed and sent by a person.","fr":"Le type d''adresse ou la pertinence de l''offre n''a pas pu être établi : le message doit être relu et envoyé par une personne."},"rules":[{"id":"offer-not-relevant","when":{"relevance":["not_relevant"]},"decision":"blocked","explain":{"en":"The offer does not relate to the recipient''s business activity, so the message cannot be justified as professional prospecting.","fr":"L''offre ne concerne pas l''activité professionnelle du destinataire : le message ne peut pas être justifié comme une prospection professionnelle."}},{"id":"generic-address-relevant","when":{"addressType":["generic","department"],"relevance":["relevant"]},"decision":"allowed_with_conditions","explain":{"en":"A generic business address (contact@, info@) is not personal data; a professional offer may be sent provided the sender is identified and an opt-out is offered from the first message.","fr":"Une adresse générique (contact@, info@) n''est pas une donnée personnelle ; une offre professionnelle peut être envoyée à condition d''identifier l''expéditeur et de proposer un désabonnement dès le premier message."}},{"id":"personal-professional-relevant","when":{"addressType":["personal"],"relevance":["relevant"]},"decision":"allowed_with_conditions","explain":{"en":"A personal professional address follows the opt-out regime (CPCE L.34-5): the offer relates to the recipient''s profession, the recipient is informed of the source and can object from the first message.","fr":"Une adresse professionnelle nominative relève du régime d''opposition (CPCE L.34-5) : l''offre concerne la profession du destinataire, qui est informé de la source et peut s''opposer dès le premier message."}},{"id":"relevance-unknown","when":{"relevance":["unknown"]},"decision":"manual_only","explain":{"en":"The link between the offer and the recipient''s profession has not been established, so a person must confirm it before sending.","fr":"Le lien entre l''offre et la profession du destinataire n''est pas établi : une personne doit le confirmer avant l''envoi."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"CNIL — Les règles d''or de la prospection par courrier électronique","url":"https://www.cnil.fr/fr/les-regles-dor-de-la-prospection-par-courrier-electronique-0"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, 'Overseas collectivity of France, not part of the EU since 2012; seeded to mirror FR, confirm locally applicable rules.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-f70508264390', NULL, 'BL', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'Overseas collectivity of France, not part of the EU since 2012; seeded to mirror FR, confirm locally applicable rules.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-f9bde4bd5913', NULL, 'BL', 'phone', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Calls to businesses are allowed with a right to object (B2B prospecting); the caller identifies themselves and the agency at the start and stops immediately on request. Calls are always placed by a person.","fr":"Les appels aux entreprises sont autorisés avec droit d''opposition (prospection B2B) ; l''appelant se présente et nomme l''agence dès le début et met fin à la démarche immédiatement sur demande. Les appels sont toujours passés par une personne."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'Overseas collectivity of France, not part of the EU since 2012; seeded to mirror FR, confirm locally applicable rules.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e0-fcf2b83e5d66', NULL, 'BL', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"SMS prospecting to businesses is not automated: a person must confirm the number belongs to the business and that the message is expected before sending, with sender identification and a STOP option.","fr":"La prospection par SMS auprès des entreprises n''est pas automatisée : une personne doit confirmer que le numéro appartient à l''entreprise et que le message est attendu avant l''envoi, avec identification de l''expéditeur et une option STOP."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"CNIL — Les règles d''or de la prospection par courrier électronique","url":"https://www.cnil.fr/fr/les-regles-dor-de-la-prospection-par-courrier-electronique-0"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'Overseas collectivity of France, not part of the EU since 2012; seeded to mirror FR, confirm locally applicable rules.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-021beb0ca05b', NULL, 'BL', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'Overseas collectivity of France, not part of the EU since 2012; seeded to mirror FR, confirm locally applicable rules.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-07d09786485d', NULL, 'DE', 'email', 1, 'seed', '{"default":"blocked","defaultExplain":{"en":"Germany requires prior express consent for email advertising, including to businesses (UWG §7); automated cold email is blocked and contact must be made manually by other means.","fr":"L''Allemagne exige un consentement exprès préalable pour la publicité par email, y compris envers les entreprises (UWG §7) ; l''emailing à froid automatisé est bloqué et le contact doit se faire manuellement par d''autres moyens."},"rules":[],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, 'No primary German source is listed in docs/compliance/outreach-compliance.md yet; add one (UWG §7) during legal review.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-0ab13d9a5507', NULL, 'DE', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-0e4ca0b5367d', NULL, 'DE', 'phone', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"B2B calls in Germany need at least presumed consent (UWG §7): a person must document why this business would plausibly welcome the call before placing it.","fr":"En Allemagne, les appels B2B nécessitent au moins un consentement présumé (UWG §7) : une personne doit documenter pourquoi cette entreprise accueillerait vraisemblablement l''appel avant de le passer."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, 'No primary German source is listed in docs/compliance/outreach-compliance.md yet; add one (UWG §7) during legal review.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-129a1ac65e6d', NULL, 'DE', 'sms', 1, 'seed', '{"default":"blocked","defaultExplain":{"en":"Electronic advertising messages in Germany require prior express consent (UWG §7); SMS prospecting is blocked.","fr":"En Allemagne, les messages publicitaires électroniques requièrent un consentement exprès préalable (UWG §7) ; la prospection par SMS est bloquée."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[]'::jsonb, 'No primary German source is listed in docs/compliance/outreach-compliance.md yet; add one (UWG §7) during legal review.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e5-72c7-97e1-17c697526fdb', NULL, 'DE', 'whatsapp', 1, 'seed', '{"default":"blocked","defaultExplain":{"en":"Electronic advertising messages in Germany require prior express consent (UWG §7), which also covers WhatsApp; the channel is blocked for prospecting.","fr":"En Allemagne, les messages publicitaires électroniques requièrent un consentement exprès préalable (UWG §7), ce qui couvre aussi WhatsApp ; le canal est bloqué pour la prospection."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, 'No primary German source is listed in docs/compliance/outreach-compliance.md yet; add one (UWG §7) during legal review.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
