INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-1da629583347', NULL, 'FR', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-221b2810f877', NULL, 'FR', 'phone', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Calls to businesses are allowed with a right to object (B2B prospecting); the caller identifies themselves and the agency at the start and stops immediately on request. Calls are always placed by a person.","fr":"Les appels aux entreprises sont autorisés avec droit d''opposition (prospection B2B) ; l''appelant se présente et nomme l''agence dès le début et met fin à la démarche immédiatement sur demande. Les appels sont toujours passés par une personne."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-2544cec39064', NULL, 'FR', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"SMS prospecting to businesses is not automated: a person must confirm the number belongs to the business and that the message is expected before sending, with sender identification and a STOP option.","fr":"La prospection par SMS auprès des entreprises n''est pas automatisée : une personne doit confirmer que le numéro appartient à l''entreprise et que le message est attendu avant l''envoi, avec identification de l''expéditeur et une option STOP."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"CNIL — Les règles d''or de la prospection par courrier électronique","url":"https://www.cnil.fr/fr/les-regles-dor-de-la-prospection-par-courrier-electronique-0"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-2b8d4c61cb65', NULL, 'FR', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-2ea8e7e866b9', NULL, 'GB', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"PECR distinguishes corporate subscribers from individuals; when the recipient type cannot be established, the message must be reviewed by a person.","fr":"Le PECR distingue les abonnés « corporate » des particuliers ; lorsque le type de destinataire ne peut pas être établi, le message doit être relu par une personne."},"rules":[{"id":"offer-not-relevant","when":{"relevance":["not_relevant"]},"decision":"blocked","explain":{"en":"The offer does not relate to the recipient''s business activity, so the message cannot be justified as professional prospecting.","fr":"L''offre ne concerne pas l''activité professionnelle du destinataire : le message ne peut pas être justifié comme une prospection professionnelle."}},{"id":"corporate-subscriber","when":{"recipientType":["legal_person"]},"decision":"allowed_with_conditions","explain":{"en":"Corporate subscribers (Ltd, LLP, PLC) may be emailed without prior consent under PECR, provided the sender is identified and an opt-out is offered.","fr":"Les abonnés « corporate » (Ltd, LLP, PLC) peuvent être contactés par email sans consentement préalable selon le PECR, à condition d''identifier l''expéditeur et de proposer un désabonnement."}},{"id":"sole-trader-or-partnership","when":{"recipientType":["sole_trader"]},"decision":"manual_only","explain":{"en":"Sole traders and partnerships are treated as individual subscribers under PECR and require consent; only a manual, consent-confirmed send is possible.","fr":"Les indépendants et partnerships sont traités comme des abonnés individuels par le PECR et requièrent un consentement ; seul un envoi manuel après confirmation du consentement est possible."}},{"id":"recipient-type-unknown","when":{"recipientType":["unknown"]},"decision":"manual_only","explain":{"en":"It is not known whether the recipient is a corporate subscriber or a sole trader; a person must check the legal form before sending.","fr":"On ignore si le destinataire est une société ou un indépendant ; une personne doit vérifier la forme juridique avant l''envoi."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"ICO — Direct marketing and privacy and electronic communications (PECR)","url":"https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-33e9894f1637', NULL, 'GB', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[{"title":"ICO — Direct marketing and privacy and electronic communications (PECR)","url":"https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-358dfd8f9bf7', NULL, 'GB', 'phone', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Calls to corporate subscribers are allowed with a right to object, after checking the number against the TPS and CTPS registers; identify yourself and stop on request.","fr":"Les appels aux sociétés sont autorisés avec droit d''opposition, après vérification du numéro dans les registres TPS et CTPS ; présentez-vous et cessez sur demande."},"rules":[{"id":"sole-trader-or-partnership","when":{"recipientType":["sole_trader"]},"decision":"manual_only","explain":{"en":"Sole traders and partnerships are individual subscribers under PECR; check the TPS register and have a person decide before calling.","fr":"Les indépendants et partnerships sont des abonnés individuels selon le PECR ; vérifiez le registre TPS et laissez une personne décider avant d''appeler."}}],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"ICO — Direct marketing and privacy and electronic communications (PECR)","url":"https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-39068ab1c5d7', NULL, 'GB', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"SMS prospecting to businesses is not automated: a person must confirm the number belongs to the business and that the message is expected before sending, with sender identification and a STOP option.","fr":"La prospection par SMS auprès des entreprises n''est pas automatisée : une personne doit confirmer que le numéro appartient à l''entreprise et que le message est attendu avant l''envoi, avec identification de l''expéditeur et une option STOP."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"ICO — Direct marketing and privacy and electronic communications (PECR)","url":"https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-3c4953fbbc8b', NULL, 'GB', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"ICO — Direct marketing and privacy and electronic communications (PECR)","url":"https://ico.org.uk/for-organisations/direct-marketing-and-privacy-and-electronic-communications/"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-421350ad1765', NULL, 'MF', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"The address type or the relevance of the offer could not be established, so the message must be reviewed and sent by a person.","fr":"Le type d''adresse ou la pertinence de l''offre n''a pas pu être établi : le message doit être relu et envoyé par une personne."},"rules":[{"id":"offer-not-relevant","when":{"relevance":["not_relevant"]},"decision":"blocked","explain":{"en":"The offer does not relate to the recipient''s business activity, so the message cannot be justified as professional prospecting.","fr":"L''offre ne concerne pas l''activité professionnelle du destinataire : le message ne peut pas être justifié comme une prospection professionnelle."}},{"id":"generic-address-relevant","when":{"addressType":["generic","department"],"relevance":["relevant"]},"decision":"allowed_with_conditions","explain":{"en":"A generic business address (contact@, info@) is not personal data; a professional offer may be sent provided the sender is identified and an opt-out is offered from the first message.","fr":"Une adresse générique (contact@, info@) n''est pas une donnée personnelle ; une offre professionnelle peut être envoyée à condition d''identifier l''expéditeur et de proposer un désabonnement dès le premier message."}},{"id":"personal-professional-relevant","when":{"addressType":["personal"],"relevance":["relevant"]},"decision":"allowed_with_conditions","explain":{"en":"A personal professional address follows the opt-out regime (CPCE L.34-5): the offer relates to the recipient''s profession, the recipient is informed of the source and can object from the first message.","fr":"Une adresse professionnelle nominative relève du régime d''opposition (CPCE L.34-5) : l''offre concerne la profession du destinataire, qui est informé de la source et peut s''opposer dès le premier message."}},{"id":"relevance-unknown","when":{"relevance":["unknown"]},"decision":"manual_only","explain":{"en":"The link between the offer and the recipient''s profession has not been established, so a person must confirm it before sending.","fr":"Le lien entre l''offre et la profession du destinataire n''est pas établi : une personne doit le confirmer avant l''envoi."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"CNIL — Les règles d''or de la prospection par courrier électronique","url":"https://www.cnil.fr/fr/les-regles-dor-de-la-prospection-par-courrier-electronique-0"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, 'EU outermost region; seeded to mirror FR.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
