INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-4fadfeab2056', NULL, 'MF', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"SMS prospecting to businesses is not automated: a person must confirm the number belongs to the business and that the message is expected before sending, with sender identification and a STOP option.","fr":"La prospection par SMS auprès des entreprises n''est pas automatisée : une personne doit confirmer que le numéro appartient à l''entreprise et que le message est attendu avant l''envoi, avec identification de l''expéditeur et une option STOP."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"CNIL — Les règles d''or de la prospection par courrier électronique","url":"https://www.cnil.fr/fr/les-regles-dor-de-la-prospection-par-courrier-electronique-0"},{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'EU outermost region; seeded to mirror FR.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-5097147203a2', NULL, 'MF', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"Legiscope — RGPD, prospection par email et SMS en B2B (summary)","url":"https://www.legiscope.com/blog/rgpd-marketing-email-sms.html"}]'::jsonb, 'EU outermost region; seeded to mirror FR.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-54d98fe8f3ac', NULL, 'NL', 'email', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"The Netherlands requires prior consent for unsolicited email, including to businesses (Telecommunicatiewet art. 11.7); without a designated address the message can only be sent manually after confirming consent.","fr":"Les Pays-Bas exigent un consentement préalable pour les emails non sollicités, y compris envers les entreprises (Telecommunicatiewet art. 11.7) ; sans adresse désignée, le message ne peut être envoyé que manuellement après confirmation du consentement."},"rules":[{"id":"designated-address","when":{"designatedForSolicitation":["yes"]},"decision":"allowed_with_conditions","explain":{"en":"The business published this address specifically to receive commercial offers, which is the exception to the consent requirement; identify the sender and offer an opt-out.","fr":"L''entreprise a publié cette adresse spécifiquement pour recevoir des offres commerciales, ce qui constitue l''exception à l''exigence de consentement ; identifiez l''expéditeur et proposez un désabonnement."}},{"id":"not-designated","when":{"designatedForSolicitation":["no","unknown"]},"decision":"manual_only","explain":{"en":"An info@ address on a contact page is not proof that it was designated for solicitation; consent is required, so only a manual, consent-confirmed send is possible.","fr":"Une adresse info@ sur une page de contact ne prouve pas qu''elle a été désignée pour la prospection ; le consentement est requis, seul un envoi manuel après confirmation du consentement est possible."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"ACM — Spam rules (Netherlands)","url":"https://www.acm.nl/nl/onderwerpen/telecommunicatie/internet/spam"},{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e6-71fa-a2c4-58d84c99300a', NULL, 'NL', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-24d95a4b9fa9', NULL, 'NL', 'phone', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Dutch cold-calling rules differ by legal form; when the recipient type is unknown a person must check it before calling.","fr":"Les règles néerlandaises sur le démarchage téléphonique dépendent de la forme juridique ; lorsque le type de destinataire est inconnu, une personne doit le vérifier avant d''appeler."},"rules":[{"id":"legal-person","when":{"recipientType":["legal_person"]},"decision":"allowed_with_conditions","explain":{"en":"Cold calls to legal persons (BV, NV) are allowed with a right to object; identify yourself and stop on request.","fr":"Les appels à froid aux personnes morales (BV, NV) sont autorisés avec droit d''opposition ; présentez-vous et cessez sur demande."}},{"id":"sole-trader","when":{"recipientType":["sole_trader"]},"decision":"blocked","explain":{"en":"Sole traders, vof and maatschap are protected like consumers: prior consent is required for cold calls.","fr":"Les indépendants, vof et maatschap sont protégés comme des consommateurs : un consentement préalable est requis pour les appels à froid."}},{"id":"recipient-type-unknown","when":{"recipientType":["unknown"]},"decision":"manual_only","explain":{"en":"It is not known whether the business is a legal person or a sole trader; a person must check the KvK register before calling.","fr":"On ignore si l''entreprise est une personne morale ou un indépendant ; une personne doit vérifier le registre KvK avant d''appeler."}}],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"ACM — Spam rules (Netherlands)","url":"https://www.acm.nl/nl/onderwerpen/telecommunicatie/internet/spam"},{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-2b912d67ac7c', NULL, 'NL', 'sms', 1, 'seed', '{"default":"blocked","defaultExplain":{"en":"Unsolicited SMS requires prior consent in the Netherlands, including to businesses (Telecommunicatiewet art. 11.7); the channel is blocked for prospecting.","fr":"Les SMS non sollicités requièrent un consentement préalable aux Pays-Bas, y compris envers les entreprises (Telecommunicatiewet art. 11.7) ; le canal est bloqué pour la prospection."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"ACM — Spam rules (Netherlands)","url":"https://www.acm.nl/nl/onderwerpen/telecommunicatie/internet/spam"},{"title":"Overloop — Dutch and Belgian cold-acquisition law overview (Sep 2026)","url":"https://overloop.com/nl/blog/koude-acquisitie-wetgeving"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-2d38e3efefb9', NULL, 'NL', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[{"title":"ACM — Spam rules (Netherlands)","url":"https://www.acm.nl/nl/onderwerpen/telecommunicatie/internet/spam"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-3063dead9bd9', NULL, 'US', 'email', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"CAN-SPAM is an opt-out regime: no prior consent is needed, but the sender must be identified, the headers and subject truthful, a postal address included and the opt-out honoured within 10 business days.","fr":"Le CAN-SPAM est un régime d''opposition : aucun consentement préalable n''est requis, mais l''expéditeur doit être identifié, l''objet et les en-têtes sincères, une adresse postale indiquée et le désabonnement traité sous 10 jours ouvrés."},"rules":[{"id":"offer-not-relevant","when":{"relevance":["not_relevant"]},"decision":"blocked","explain":{"en":"The offer does not relate to the recipient''s business activity, so the message cannot be justified as professional prospecting.","fr":"L''offre ne concerne pas l''activité professionnelle du destinataire : le message ne peut pas être justifié comme une prospection professionnelle."}}],"requiredElements":["sender_identity","postal_address","opt_out_link","unsubscribe_headers","source_disclosure","relevance","recipient_language","honest_subject"]}'::jsonb, '[{"title":"FTC — CAN-SPAM Act: a compliance guide for business","url":"https://www.ftc.gov/business-guidance/resources/can-spam-act-compliance-guide-business"},{"title":"RFC 8058 — Signaling one-click functionality for List-Unsubscribe","url":"https://www.rfc-editor.org/rfc/rfc8058"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-366e824df12f', NULL, 'US', 'letter', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Postal mail to a business at its published address is allowed: identify the sender and agency, state where the address was found, write in the recipient''s language and honour any objection.","fr":"Le courrier postal adressé à une entreprise à son adresse publiée est autorisé : identifiez l''expéditeur et l''agence, indiquez où l''adresse a été trouvée, écrivez dans la langue du destinataire et respectez toute opposition."},"rules":[],"requiredElements":["sender_identity","postal_address","source_disclosure","recipient_language"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-3b146f7265cf', NULL, 'US', 'phone', 1, 'seed', '{"default":"allowed_with_conditions","defaultExplain":{"en":"Calls to businesses are allowed with a right to object (federal and state telemarketing rules mainly target consumers); the caller identifies themselves and the agency at the start and stops immediately on request. Calls are always placed by a person.","fr":"Les appels aux entreprises sont autorisés avec droit d''opposition (les règles fédérales et des États sur le télémarketing visent surtout les consommateurs) ; l''appelant se présente et nomme l''agence dès le début et met fin à la démarche immédiatement sur demande. Les appels sont toujours passés par une personne."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, 'B2B calls are generally allowed (manual); check state-level rules during legal review.', true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-3ebe7ef4d6ad', NULL, 'US', 'sms', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"SMS prospecting to businesses is not automated: a person must confirm the number belongs to the business and that the message is expected before sending, with sender identification and a STOP option.","fr":"La prospection par SMS auprès des entreprises n''est pas automatisée : une personne doit confirmer que le numéro appartient à l''entreprise et que le message est attendu avant l''envoi, avec identification de l''expéditeur et une option STOP."},"rules":[],"requiredElements":["sender_identity","opt_out_link","stop_on_request"]}'::jsonb, '[{"title":"FTC — CAN-SPAM Act: a compliance guide for business","url":"https://www.ftc.gov/business-guidance/resources/can-spam-act-compliance-guide-business"}]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "compliance_policies" ("id", "organization_id", "jurisdiction", "channel", "version", "kind", "rules", "sources", "note", "needs_legal_review") VALUES ('01a1495d-43e7-75d7-a062-41ea8e5029a5', NULL, 'US', 'whatsapp', 1, 'seed', '{"default":"manual_only","defaultExplain":{"en":"Only human-initiated click-to-chat conversations are supported: a person opens the chat, identifies themselves and the agency, and stops on request. Automated business-initiated messaging is not used.","fr":"Seules les conversations « click-to-chat » ouvertes par une personne sont prises en charge : elle se présente, nomme l''agence et cesse sur demande. Aucun envoi automatisé à l''initiative de l''entreprise n''est utilisé."},"rules":[],"requiredElements":["identify_on_call","stop_on_request"]}'::jsonb, '[]'::jsonb, NULL, true) ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "offer_relevance" ("id", "offer", "taxonomy_prefix", "relevant", "rationale", "position") VALUES ('01a1495d-43e7-75d7-a062-4528f08fc1c2', 'new_website', '', true, '{"en":"Every customer-facing local business benefits from a website that presents its activity, hours and contact details.","fr":"Toute entreprise locale recevant du public bénéficie d''un site qui présente son activité, ses horaires et ses coordonnées."}'::jsonb, 0) ON CONFLICT DO NOTHING;
