INSERT INTO "offer_relevance" ("id", "offer", "taxonomy_prefix", "relevant", "rationale", "position") VALUES ('01a1495d-43e7-75d7-a062-80a46fff2417', 'ai_receptionist', '', false, '{"en":"Other categories do not rely on inbound calls or appointments, so an AI receptionist does not relate to their activity.","fr":"Les autres catégories ne reposent pas sur des appels entrants ou des rendez-vous ; un standard IA ne concerne pas leur activité."}'::jsonb, 15) ON CONFLICT DO NOTHING;
