INSERT INTO "offer_relevance" ("id", "offer", "taxonomy_prefix", "relevant", "rationale", "position") VALUES ('01a1495d-43e7-75d7-a062-b5e404926018', 'booking_system', '', false, '{"en":"Other categories do not sell time slots or reservations, so a booking system does not relate to their activity.","fr":"Les autres catégories ne vendent ni créneaux ni réservations ; un système de réservation ne concerne pas leur activité."}'::jsonb, 28) ON CONFLICT DO NOTHING;
